const fs = require('fs');
const path = require('path');

const root = process.env.SKILLS_HUB_PATH || '/skills';
const skill = $input.first().json.skill;

if (!skill) {
  throw new Error('Input must include a "skill" field, e.g. { "skill": "find-skills" }');
}

const candidates = [
  path.join(root, 'vendor', skill, 'SKILL.md'),
  path.join(root, 'custom', skill, 'SKILL.md'),
];

let filePath = null;
for (const candidate of candidates) {
  if (fs.existsSync(candidate)) {
    filePath = candidate;
    break;
  }
}

if (!filePath) {
  return [{
    json: {
      skill,
      found: false,
      error: `No SKILL.md found for "${skill}" under ${root}/vendor or ${root}/custom`,
    },
  }];
}

const raw = fs.readFileSync(filePath, 'utf8');
const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);

let name = skill;
let description = '';
let body = raw;

if (match) {
  const frontmatter = match[1];
  body = match[2].trim();
  const nameMatch = frontmatter.match(/^name:\s*(.+)$/m);
  const descMatch = frontmatter.match(/^description:\s*(.+)$/m);
  if (nameMatch) name = nameMatch[1].trim();
  if (descMatch) description = descMatch[1].trim();
}

return [{
  json: {
    skill,
    found: true,
    path: filePath,
    name,
    description,
    body,
    raw,
  },
}];
